package com.fortune.stall.engine.jishiyu

/** 潜虚筮法数据表：由原版 ji.js.cn / yu2102897706.github.io/qianxu 反编译还原，55 名。 */
object QianxuData {

    data class PosInfo(val ji: String, val ci: String, val xiang: String, val dayi: String)
    data class Ming(
        val key: String, val name: String, val def: String, val wx: String,
        val total: String, val pos: Map<String, PosInfo>, val yi: String
    )

    val DATA: List<Ming> = listOf(
        Ming("11", "元", "元，始也。夜半，日之始也；朔，月之始也；冬至，岁之始也；好学，智之始也；力行，道德之始也；任人，治乱之始也", "水", "慎于举趾，差则千里，机正其矢||慎于举趾，差则远矣", emptyMap(), "元就是开始：半夜是一天的开始，初一是一月的开始，冬至是一年的开始；好学是智慧的开始，力行是道德的开始，用人得当是国家治乱的开端。"),
        Ming("12", "裒", "裒，聚也。气聚而物，宗族聚而家，圣贤聚而国", "火", "", mapOf("初" to PosInfo("吉凶不现", "进而逡而，俟其信而，利用正", "聚不可苟，必进逡也", "聚集不能勉强，先谨慎试探、取得信任再前进，宜守正道。"), "二" to PosInfo("平", "人裸而繁，兽猛而殚", "人裸而繁，善以道群也", "合群靠道义不靠蛮力：人知礼而繁衍昌盛，兽恃猛而衰亡。"), "三" to PosInfo("凶", "百毒之聚，胜者为主，惟物之蛊", "百毒之众，止害人也", "像百毒聚成蛊一样，一群恶人强者称王，最终害人害己。"), "四" to PosInfo("臧", "羽毛鳞介，各从其彚", "羽毛鳞介，聚以伦也", "飞禽、走兽、鳞介各按族类聚集，物以类聚，顺其自然。"), "五" to PosInfo("否", "莬丝之棼，附草绝根", "莬丝之棼，不知固根也", "像菟丝子缠草，只靠攀附别人，反把自己的根基断绝了。"), "六" to PosInfo("吉", "八音和鸣，神祗是听", "八音之裒，感人神也", "八音和鸣和谐成曲，能感动神灵，和气致祥。"), "上" to PosInfo("吉凶不现", "云还于山，水泮于川", "云还水泮，聚极必分也", "云散回山、冰化入川，聚到极点必然要散，凡事见好就收。")), "裒就是聚合：元气聚合生成万物，族人聚合成为家族，圣贤聚合而成国家。"),
        Ming("13", "柔", "柔，地之德也，臣之则也。天为刚矣，不逆四时；君为刚矣，不却嘉谋；金为刚矣，从人所为；故刚而不柔，未有能成者也。", "木", "", mapOf("初" to PosInfo("吉凶不现", "马牛服役，左右殚力", "马牛服役，臣职宜也", "像马牛服役一样任劳任怨，是臣下应尽的本分。"), "二" to PosInfo("凶", "蘧蒢戚施，盗跖之祈，或得其笞", "盗跖之祈，靡不为也；或行其笞，为主所知也", "靠谄媚讨好人，什么丑事都肯做，结果多半挨鞭子、被主上识破。"), "三" to PosInfo("平", "齿刚必缺，久存者舌", "齿缺舌存，久刚必危也", "牙齿太硬先掉，舌头柔软长存；一味逞强必招危险。"), "四" to PosInfo("臧", "蜚石之落，抗之以幕", "蜚石之落，强不能支也", "飞石砸下硬挡挡不住，以柔接之（用帷幕承）才免伤。"), "五" to PosInfo("吉", "大柔如水，利物无已", "大柔如水，不与物违也", "真正的柔像水一样，滋养万物从不与物相争，故吉。"), "六" to PosInfo("否", "蒲梁柳毂，倾榱脱辐", "蒲梁柳毂，任重力微也", "用蒲草做梁、柳木做车毂，硬扛重担只会倾覆散架。"), "上" to PosInfo("吉凶不现", "缀旒靡委，政不在己", "缀旒靡委，君道非也", "软弱到像垂下的旗旒一样无力，大权旁落，为君之道已失。")), "柔是大地之德、为臣之道。天虽刚却不违背四时，君虽刚却不拒绝良谋，金属虽刚却随人锻用；只刚不柔，成不了事。"),
        Ming("14", "刚", "刚，天之道也，君子之守也；地为柔矣，负载山岳；臣为柔矣，正值谔谔；水为柔矣，颓厓穿石；故柔而不刚，未有能立者也", "金", "", mapOf("初" to PosInfo("吉凶不现", "偃王无骨，莫之自立", "人之有骨，以自立也", "人要有骨气才能自立，软骨头立不起来。"), "二" to PosInfo("否", "不忍小辱，自经沟渎", "自经沟渎，小人决也", "受不了一点小委屈就寻短见，是小人的决绝，不是大丈夫。"), "三" to PosInfo("凶", "目瞋耳塞，拔木触石，一跌而踣，蝼蚁之食", "一跌而踣，不复振也", "发怒到目瞋耳塞、见什么撞什么，一跌不起，反成蝼蚁口中食。"), "四" to PosInfo("吉", "金与玉轴，历险不覆", "金与玉轴，任重载也", "像金轴玉轮的车，正派结实，再险的路也不会翻。"), "五" to PosInfo("平", "介洁自守，其要无咎", "其要无咎，由寡欲也", "洁身自好守住分寸，能无咎是因为欲望少。"), "六" to PosInfo("臧", "精金百链，有折无卷", "有折无卷，质不渝也", "真金百炼宁折也不卷，刚正之质始终不变。"), "上" to PosInfo("吉凶不现", "欧冶铸剑，利用加锡", "利用加锡，过刚则折也", "连铸剑都要加点锡来柔化——过于刚硬就会折断，刚中要有柔。")), "刚是天之道、君子的操守。地虽柔能承载山岳，臣虽柔却正直敢言，水虽柔能冲刷穿石；只柔不刚，立不起来。"),
        Ming("15", "雍", "雍，和也，天地万物之性。不刚则柔，不晦则明，而通行之，其在和平", "土", "", mapOf("初" to PosInfo("吉凶不现", "匪飞匪潜，出门交有功", "出门交有功，尚和也", "不飞不潜、不偏不激，出门与人交往以和为贵，能得助力。"), "二" to PosInfo("臧", "柳下惠不易其介，伯夷怨是用希", "夷清不偏，惠和不流也", "伯夷清高而不偏激，柳下惠随和而不流俗，各守其和。"), "三" to PosInfo("吉", "玉质金声，利用陈于帝庭", "玉质金声，有嘉德也", "德如玉质、声如金鸣，有这种嘉德，自可登堂入室。"), "四" to PosInfo("凶", "狺狺额额，无施而适，搏沙杂砾，舒席卷棘", "狺狺额额，不可如何", "整天龇牙咧嘴地争闹，像把沙砾搅在一起、用席子卷荆棘，乱成一团。"), "五" to PosInfo("平", "鬻者减，求者增，卒会于平", "鬻减求增，益寡损多也", "卖的低、买的加，两下相就，最终在「平」上成交。"), "六" to PosInfo("否", "盐梅不适，羹弃不食", "盐梅不适，性有颇也", "盐和梅的比例不对，整锅羹都被倒掉——和不得当，反成灾。"), "上" to PosInfo("吉凶不现", "天地融融，万物雍雍", "天地融融，万物和也", "天地之气融融洽洽，万物一片和乐，这是和的最高境界。")), "雍就是和，是天地万物的本性：不是刚就是柔，不是晦就是明，能贯通这一切的，靠的是平和。"),
        Ming("16", "昧", "昧，晦也。日之晦，昼夜以成，月之晦，弦望以生，君子之晦，与时偕行", "水", "", mapOf("初" to PosInfo("吉凶不现", "取足于己，不知外美", "取足于己，所以昧也", "只满足于自己那点见识，看不到外面的好，所以昏暗。"), "二" to PosInfo("吉", "日匿其光，徯于东方", "日匿其光，德未耀也", "太阳暂时藏起光芒，是在等升于东方；人晦藏是为日后显耀。"), "三" to PosInfo("凶", "铁目石耳，蹈于渊水", "铁目石耳，不可导也", "耳目像铁石一样听不进劝，最终栽进深渊，谁也救不了。"), "四" to PosInfo("臧", "冥行失足，或导之烛", "或导之烛，能受教也", "摸黑走路跌了跤，肯听人举灯指路，就能走出迷途。"), "五" to PosInfo("平", "无相之瞽，阖户而处", "阖户而处，未失道也", "没人引导的盲人闭门安处，虽看不见却不失道，安分即平。"), "六" to PosInfo("否", "不习而斲，败材毁朴", "不习而斲，不免咎也", "不学手艺就乱动刀斧，白白毁了好材料，免不了出错。"), "上" to PosInfo("吉凶不现", "偶人守金，众盗攸侵", "以昧居上，必有盗也", "像木偶守金库一样昏聩在上位，各路盗贼必然来侵。")), "昧就是晦暗。日有晦暗才有昼夜，月有晦暗才有圆缺，君子也有藏锋之时，与时机同行。"),
        Ming("57", "昭", "昭，明也。天地之明，靡不察也；日月之明，靡不烛也；人君之明，官君材也；怛有辜也，懋有功也", "火", "", mapOf("初" to PosInfo("吉凶不现", "奁其鉴，拂其尘，觌其形", "奁鉴拂尘，以自照也", "打开镜匣、擦去灰尘照见自己——先把自己照清楚，才能明察。"), "二" to PosInfo("平", "隋珠照夜，不如膏烛", "珠能照夜，不可常也", "隋侯珠再亮也不能常点，不如油灯实用——聪明要用在长远处。"), "三" to PosInfo("凶", "察穷秋毫，物骇而逃", "察穷秋毫，物所骇也", "明察到连秋毫都苛究，身边的人都被吓跑，过分明察反成祸。"), "四" to PosInfo("臧", "凿隙偷光，厥志唯勤，争畀之烛", "凿隙偷光，善借明也；争畀之烛，遂光大也", "凿壁偷光那样苦读勤学，别人都愿意把烛火借他——勤勉可引光明。"), "五" to PosInfo("否", "循墙不蹶，秉烛而跌", "秉烛而跌，恃明懈也", "扶墙慢慢走不摔，举着明烛大步走反而摔了——仗着看得清就松懈，反招跌。"), "六" to PosInfo("吉", "日丽于天，万物粲然", "日丽于天，无不照也", "太阳悬在天上，万物无不光辉粲然——大光明普照，无不察。"), "上" to PosInfo("吉凶不现", "宿火于灰", "宿火于灰，善养明也", "把火种藏在灰里慢慢养——真正的明智懂得蓄养，不轻易外露。")), "昭就是明。天地之明无所不察，日月之明无所不照，君主之明在于任用贤才，怜惜有罪、嘉奖有功。"),
        Ming("33", "容", "容，貌也。尊卑有仪，军国有容，舍之则厖。", "木", "", mapOf("初" to PosInfo("吉凶不现", "修而贯而，久而安而", "修容有常，久则贯也", "把仪容修整变成习惯，久了自然安详得体。"), "二" to PosInfo("凶", "葆首夷俟，不若遄死", "葆首夷俟，不可忍见也", "蓬头垢面、吊儿郎当，那副样子让人看不下去，不如死了干净。"), "三" to PosInfo("平", "颒面不饰", "颒面不饰，质不变也", "只洗脸不涂饰，本来的面目不变——朴素自守，无可无不可。"), "四" to PosInfo("臧", "褧衣锦里，君子养美", "褧衣锦里，不自绚也", "锦衣穿在里面、粗布罩在外面，君子涵养美德而不自我炫耀。"), "五" to PosInfo("吉", "如圭如璋，以和以庄", "以和以庄，容之善也", "像圭璋一样温润端正，和蔼又庄重，是仪容的最好状态。"), "六" to PosInfo("否", "朱襮紫里，服久必敝", "朱襮之敝，其里见也", "外面朱红、里子紫色，穿久了磨破就露出里子——装出来的体面撑不久。"), "上" to PosInfo("吉凶不现", "樛木之垂，甘瓠之累", "木垂瓠累，贵下贱也", "大树弯下枝条才结满葫芦——居于上而能下，谦下反得繁盛。")), "容就是仪容。尊卑各有礼节，军国讲究威仪，丢了这些就会杂乱无章。"),
        Ming("34", "言", "言，辞也。有雷有风，天心始通；有号有令，君心无隐；有话有言，中心乃宣。", "金", "", mapOf("初" to PosInfo("吉凶不现", "壶囊之口，可用以受；喑者之食，稻粱之贼", "稻粱之贼，言不可已也", "壶囊有口才能装东西；哑巴只会吃不会说，成了白吃粮食的。话还是要说。"), "二" to PosInfo("否", "人不我知，馈金而疑", "馈金而疑，人弗信也", "人不了解你时，送金子反而招怀疑——话说不到点上，诚意也白搭。"), "三" to PosInfo("凶", "不固其关，祸溢浮天", "祸溢浮天，不可收也", "嘴上不把门，祸就像水决堤漫上天，想收也收不回。"), "四" to PosInfo("吉", "天信其时，万物攸期", "万物攸期，素信之也", "天说话算数、四时不爽，万物才有所期待——守信是最大的吉。"), "五" to PosInfo("平", "庸言之谨，必顾其行", "庸言之谨，以立诚也", "连平常话都谨慎出口、说到做到，靠这个立起诚信。"), "六" to PosInfo("臧", "时言之利，上下攸赖", "上下攸赖，其利溥也", "话说得合时合宜，上下都受益，好处广大。"), "上" to PosInfo("吉凶不现", "言由于德，弗思而得，万世之式", "言由于德，非意之也；万世之式，当于理也。", "话从德行里自然流出，不用刻意琢磨，合于道理，可为万世典范。")), "言就是言辞。有雷有风，天意才得以传达；有号有令，君心才没有隐晦；有话有言，心中所想才得以表达。"),
        Ming("35", "虑", "虑，思也。圣人无思，自合于宜；贤者之思，以求其时。临事不思，不能研几；学道不思，不能造微", "土", "", mapOf("初" to PosInfo("吉凶不现", "秋毫差机，矢不可追", "秋毫差机，不可不慎也", "起念差之毫厘就全盘走偏，像射出的箭追不回来——开头最要谨慎。"), "二" to PosInfo("臧", "旁瞻千里，却顾百世", "旁瞻却顾，所虑远也", "眼光前看千里、后顾百世，思虑深远，这是善虑。"), "三" to PosInfo("吉", "澄源正本，执天之键", "澄源正本，万术尽也", "从源头上澄清、从根本上摆正，等于握住天机钥匙，万事都在掌握。"), "四" to PosInfo("凶", "林甫月室，愠入笑出，匪躬之益", "匪躬之益，终自及也", "像李林甫那样当面笑背后害，算计别人终会报应到自己头上。"), "五" to PosInfo("平", "万物之神，出天入尘", "出天入尘，无不轃也", "思虑通达可上天下地，但也要落回实处，才不流于空想。"), "六" to PosInfo("否", "谋利忘寝，商贾之任", "谋利忘寝，思不远也", "一心只盘算私利、觉都睡不安，那是商贩的眼界，想得不远。"), "上" to PosInfo("吉凶不现", "孔子从心，不逾矩", "孔子从心，从容中道也", "孔子七十随心所欲也不越规矩——思虑成熟到化境，自然而然合于道。")), "虑就是思考。圣人不用刻意思虑自然合宜，贤者思虑是为了把握时机；遇事不思看不出细微，学道不思达不到精微。"),
        Ming("36", "聆", "聆，听也。天下其耳，舜达四聪，听而不闻是谓耳聩，闻而不择，是谓心聋。所以王者听德惟聪，学者非礼不听。", "水", "", mapOf("初" to PosInfo("吉凶不现", "听德惟聪，否不若聋", "否不若聋，闻无益也", "听正道才算耳聪；听不进好话，还不如聋了。"), "二" to PosInfo("吉", "黈纩弗彻，舜聪四达", "舜聪四达，聪不蔽也", "耳朵不被堵塞，像舜那样听得见四方，聪慧通达。"), "三" to PosInfo("凶", "甘言便耳，没于渊水", "甘言便耳，不可悦也", "甜言蜜语听着顺耳，信了就沉进深渊——好听的话要提防。"), "四" to PosInfo("臧", "苦言刺耳，惟身之利", "苦言利身，不可恶也", "逆耳的话刺人，却是真正对你有益，别嫌弃。"), "五" to PosInfo("平", "卑听惟顺，择其利病", "择其利病，由乎心也", "放低姿态听人说话，再用自己的心分辨利害，这才是会听。"), "六" to PosInfo("否", "蚁斗闻声，惟迩言是听", "迩言是听，心不逮耳也", "耳朵灵到听蚂蚁打架，却只信身边人的小话——心跟不上耳朵。"), "上" to PosInfo("吉凶不现", "圣人无择，恶声不入", "恶声不入耳，不顺非也", "圣人心正，邪言恶语自然进不了耳朵，不听就不顺非。")), "聆就是听。舜通达四方之聪；听了却没听进去叫耳聋，听了不会辨别叫心聋。所以君王只听有德之言，学者不合礼的不听。"),
        Ming("37", "觌", "觌，视也。天高其目，舜明四目。视而弗见，是谓目盲；见而弗择，是谓心瞽。所以王者视远惟明，学者非礼勿视", "火", "", mapOf("初" to PosInfo("吉凶不现", "粉泽之晖，覆阱埋机，昧者不知，明者识微", "昧者不知，目诱之也", "粉饰的光彩底下藏着陷阱，糊涂人看不破，明眼人早看出端倪。"), "二" to PosInfo("平", "项楚姚虞，形似心殊", "形似心殊，明不在目也", "有人形貌相似、心性迥异——看人不能只看表面，明辨靠心不靠眼。"), "三" to PosInfo("凶", "驰车击毂，自掩其目，垣途犹覆", "自掩其目，不能见也", "车跑得飞快还自己蒙住眼睛，再直的路也照样翻车。"), "四" to PosInfo("臧", "虎视耽耽，其心潭潭", "其心潭潭，审所视也", "目光灼灼如虎视，心里却沉静如水——看准了才动。"), "五" to PosInfo("否", "蘧蒢戚施，俯仰相疑", "俯仰相疑，任偏见也", "只凭偏见看人，看谁都像谄媚的小人——偏见蒙住了眼睛。"), "六" to PosInfo("吉", "漆器象箸，因微知著，离娄之目，视细犹巨", "视细犹巨，明辨皙也", "从一双象牙筷看出奢侈的开端，见微知著——看得细，才是真的看得清。"), "上" to PosInfo("吉凶不现", "凝旒十二，惟目之蔽，同仁一视", "凝旒之蔽，不用目也", "冕旒垂下虽遮视线，却提醒人君不靠肉眼、一视同仁。")), "觌就是看。舜有明察四方的眼力；看了却没看见叫眼盲，看见不会辨别叫心瞎。所以君王看事要看得远、看得明，学者不合礼的不看。"),
        Ming("38", "繇", "繇，喜也。天地同春，万物忻忻，圣贤相逢，四海归仁", "木", "", mapOf("初" to PosInfo("吉凶不现", "凯风怡怡，万物熙熙", "凯风怡怡，怒气散也；万物熙熙，无疾惫也", "和风习习，万物和乐——怒气消了，一片祥和。"), "二" to PosInfo("凶", "悦之匪人，涉于幽榛，覆车陷轮", "悦之匪人，徇所爱也", "讨好错了对象，走进幽暗丛林，车翻轮陷——欢喜给了不该给的人。"), "三" to PosInfo("平", "爰笑爰语，神清心与，弗丧其斧", "弗丧其斧，未失则也", "说说笑笑神清气爽，但没丢掉自己的「斧头」——原则没丢，就不失分寸。"), "四" to PosInfo("臧", "闻谤而喜，反求诸己", "闻谤而喜，以从道也", "听到别人批评反而高兴，回头检查自己——把谤言当镜子，是修道的态度。"), "五" to PosInfo("吉", "喜怒以律，爱恶不失，大人元吉", "大人元吉，不失律也", "喜怒都按规矩来，爱憎不失分寸，大人如此自然大吉。"), "六" to PosInfo("否", "赏溢于喜，重器是委，或颠而毁", "赏溢于喜，爱人从政也", "一高兴就滥赏，把权柄重器轻易交给别人，迟早颠仆毁败。"), "上" to PosInfo("吉凶不现", "爵禄锡予，饰喜之具，惜印吝金，人委而去", "爵禄饰喜，不虚拘也；惜印吝金，人失望也", "爵禄本是表达喜悦的工具；若只挂在嘴上、舍不得真给，人心就散了、人都走了。")), "繇就是喜悦。天地同春，万物欣欣，圣贤相逢，四海归向仁德。"),
        Ming("89", "懠", "懠，怒也。天地之怒，风霆横飞；王者之怒，爰整六师；君子之怒，暴乱是夷；小人之怒，适为身菑", "金", "", mapOf("初" to PosInfo("吉凶不现", "匪怒之遒，必理之求，拔刃难收", "必理之求先虑后断也", "怒不可急发，先弄清道理再定；刀一旦拔出就难收回。"), "二" to PosInfo("否", "自怒自解，人不之畏", "自怒自解，威已玩也", "发火又自己消掉，反反复复，没人再当回事——威仪被自己玩没了。"), "三" to PosInfo("凶", "快心一朝，忘其宗祧，失不可招，鯸臣之浮，乌鸢之求", "快心一朝，忘后患也", "为图一时痛快不管后果，连根本都忘了——失去的再也找不回，成了乌鸦老鹰争食的下场。"), "四" to PosInfo("吉", "雷霆赫赫，乱是用息，狼贉死国", "雷霆赫赫，以止乱也", "该怒时像雷霆一样发作，乱子才被压住——有威怒才能止乱，虽死卫国。"), "五" to PosInfo("平", "有众有形，怒然后兴", "无形而怒，祇取嫚也", "有实力有凭据才发怒；没凭没据乱发火，只招人轻慢。"), "六" to PosInfo("臧", "忍之少时，福禄无期", "忍之少时，迺免难也", "忍这一时片刻，就能免掉大祸，福禄还在后头。"), "上" to PosInfo("吉凶不现", "雷风既息，继以沛泽", "风息而雨，群物浣也", "雷霆过后必有甘雨——怒极转和，万物反得滋润。")), "懠就是怒。天地发怒风雷大作，王者发怒整军讨伐，君子发怒铲平暴乱，小人发怒只会给自己招灾。"),
        Ming("810", "得", "得，欲也。牝牡饮食，禽兽之识；官爵财利，仆隶之志；欲仁求仁，入自圣门", "土", "", mapOf("初" to PosInfo("吉凶不现", "耳目鼻口，外交中诱，惟心之咎", "外交中诱，心不君也", "耳目口鼻被外物勾引，心这个「君主」管不住它们，毛病就出在心上。"), "二" to PosInfo("臧", "以礼制心，成汤之德；汉高入关，弗徇货色", "弗徇货色，智之事也", "用礼约束欲望，像成汤、像刘邦入关不贪财色——能克制，是明智。"), "三" to PosInfo("吉", "圣人徇理，百物不废，其心无累", "其心无累，过不留也", "圣人顺着道理行事，万物都为我用而不被牵累——心无挂碍，事过不留。"), "四" to PosInfo("凶", "豨腹饕饕，为人益膏", "豨腹饕饕，贪欲不厌也", "贪心像猪肚子一样填不满，最后反成了别人案板上的肉。"), "五" to PosInfo("平", "守常知足，不危不辱", "不危不辱，又何求也", "守住本分、知道满足，不冒风险不受羞辱，还求什么呢？"), "六" to PosInfo("否", "不学无义，惟饮食牝牡之嗜，禽兽之毙", "禽兽之毙，犹可食也", "不读书不讲义，只惦记吃喝和男女，跟禽兽一样死法。"), "上" to PosInfo("吉凶不现", "鸱争腐鼠，鹓雏弗顾", "腐鼠弗顾，乃可贵也", "猫头鹰抢臭老鼠当宝，凤凰看都不看——志趣高的人，不为俗物所动。")), "得就是欲望。饮食男女是禽兽的本能，求官发财是小人的志向；而追求仁德，才进得了圣贤之门。"),
        Ming("81", "罹", "罹，忧也。知命乐天，无忧则贤；乐天知命，有忧则圣；若夫涉世应事则有常理：始于忧勤，终于逸乐；人无远虑，必有近忧", "水", "", mapOf("初" to PosInfo("吉凶不现", "饱食无忧，襟裾马牛", "襟裾马牛，人必有忧也", "吃饱就睡、无忧无虑，跟牛马有什么两样——人活着总该有所忧。"), "二" to PosInfo("吉", "巨舰之峨，衡风激波，济于江河，先哭后歌", "先哭后歌，忧则有喜也", "大船顶着风浪渡江，先哭后歌——先忧后喜，忧过才有喜。"), "三" to PosInfo("凶", "火在薪下，安寝不惧", "安寝不惧，无所知也", "火已经在柴堆底下烧起来，还安稳大睡——看不见隐患，最危险。"), "四" to PosInfo("臧", "德谊不积，惟躬之戚", "德谊不积，贤者之忧也", "德行道义没积起来，这是贤者真正该忧虑的事。"), "五" to PosInfo("平", "嫠妇之悴，匪知其纬", "嫠不恤纬，知所忧也", "寡妇不愁自己织布，却忧国家安危——忧虑在公不在私，是可贵的忧。"), "六" to PosInfo("否", "杞人蚩蚩，忧天之堕", "忧天之堕，亦过计也", "整天担心天会塌下来——忧虑过头，是多余的算计。"), "上" to PosInfo("吉凶不现", "周规孔制，后世之计", "周规孔制，忧万世也", "周公制礼、孔子立教，是为万世操心——这才是最深远的忧。")), "罹就是忧。乐天知命而无忧可称贤，乐天知命仍有忧可称圣；处世有常理：从忧勤开始，到安乐结束；人没有长远的考虑，必有眼前的忧患。"),
        Ming("82", "湛", "湛，乐也。以欲忘道，惑而不乐；以道制欲，乐而不乱；去欲从道，其乐也诚。情有七而虚其五，何也？人喜斯爱之，怒斯恶之，故喜怒所以兼爱恶也", "火", "", mapOf("初" to PosInfo("吉凶不现", "利用作室，冈惮于勤，大厦以成，妇子欣欣", "妇子欣欣，享其安也", "不怕辛苦盖房子，大厦落成，妻儿欢欢喜喜——先勤后乐，乐得踏实。"), "二" to PosInfo("平", "万民不区，守业安居，形容心愉", "形苦心愉，内自适也", "不折腾、守本业、安居乐业，身体虽劳心里畅快——乐由内出。"), "三" to PosInfo("凶", "醉饱之惛，歌舞之纷，突火将焚，盗倚其门", "醉饱之惛，忘躬之戚也", "吃喝醉饱、歌舞喧腾，火都要烧屋、盗贼都靠门了还不知道——乐极生悲。"), "四" to PosInfo("臧", "酒食衎衎，威仪反反，绳墨不远", "酒食衎衎，以礼自饬也", "酒席上吃得高兴，却仍保持威仪、不离规矩——乐而有礼。"), "五" to PosInfo("否", "不勤厥亩，丧其稷黍", "不勤厥亩，无以食也", "不勤耕种，庄稼全丢——只顾眼前的乐，忘了本分，饭都没得吃。"), "六" to PosInfo("吉", "家有韶濩，外记其慕", "家有韶濩，乐道德也", "家里奏着雅乐，心里乐的是道德——以道为乐，才是真乐。"), "上" to PosInfo("吉凶不现", "王用宴于镐京", "镐京之宴，乐以天下也", "君王在镐京设宴——与天下同乐，才是最高级的乐。")), "湛就是乐。纵欲忘道，迷惑而不快乐；以道制欲，快乐而不乱；舍弃私欲顺从道，快乐才真诚。"),
        Ming("88", "歬", "歬，进也。驽马日进，骐骥可及；学者日进，圣门可入；为国日进，功业可得；险途冒进，或至于踣。", "木", "", mapOf("初" to PosInfo("吉凶不现", "歬非获已，进寸退咫，饰其金履", "歬进之初，不可不慎也", "前进不是硬来，进一寸退一尺地试探——起步最要谨慎，别只顾装点门面。"), "二" to PosInfo("凶", "盲人操舟，乘彼湍流", "盲人操舟，祸在不振也", "瞎眼的人撑船闯急流，看不清方向，祸事就在眼前。"), "三" to PosInfo("平", "日出而征，日没而息，君子之则", "君子之则，出处顺也", "太阳出来就出发，落了就歇——进退出处顺着时势，是君子的法则。"), "四" to PosInfo("臧", "免跳而跼，鸟飞而伏，弧张肘缩", "兔跳而跼，以退为进也", "兔子要跳先蹲下，鸟要飞先收翅——先退一步，才能进得有力。"), "五" to PosInfo("吉", "主人三宿，日中必暴，失时不逐", "主人三宿，征勿问也", "时机到了还不行动，就像日中不晒粮——错过时机就别硬追。"), "六" to PosInfo("否", "驽马之疲，骥马之追，鷇羽强飞，坠于藩篱", "驽马追骥，力疲尽也", "劣马硬追千里马，雏鸟羽毛没长全就强飞——不自量力，只会摔在篱笆边。"), "上" to PosInfo("吉凶不现", "日没而征，力惫而登，遇棹逢兵", "日没而征，危辱近也", "太阳落山才赶路、精疲力竭才往上爬，又遇船桨又逢兵——危辱就在眼前。")), "歬就是前进。劣马天天前进也能赶上千里马；学者天天进步能进圣门；治国天天进取能建功业；但险路上冒进，可能跌倒。"),
        Ming("59", "却", "却，退也。日月进退，晦明以成；寒暑进退，物品以生；君子进退，功名以彰", "金", "", mapOf("初" to PosInfo("吉凶不现", "一叶于蜚，木阴未稀，我心伤悲", "一叶于蜚，阴始长也", "一叶落而知秋——阴气开始长了，该有退意，所以伤悲。"), "二" to PosInfo("否", "纳履而顾，心留迹去", "纳履而顾，心有望也", "鞋都穿好了要走，还频频回头看——心里还存着指望，退不干净。"), "三" to PosInfo("凶", "唾面不辱，叱嗟不缩，或挤诸谷", "唾面不辱，颜之强也", "被人唾脸也不擦、喝骂也不退，硬撑到底，结果被人挤下深谷。"), "四" to PosInfo("吉", "云蜚于江，舟藏于浦，雷出于人，车税于宇", "云蜚于江，识微象也", "看云知道要下雨、看雷知道要收车——见微知著，早作退藏，是吉。"), "五" to PosInfo("平", "揖之则歬，麾之则止，喜愠无喜", "揖歬麾止，动不妄也", "人家招手就进、挥手就停——进退看信号，不妄动，喜怒不形于色。"), "六" to PosInfo("臧", "膳珍不御，致鼎而去，勿须其饫", "膳珍不御，志不享也", "珍馐摆上不贪口，鼎还没上完就告退——懂得知足而退，不恋口腹之享。"), "上" to PosInfo("吉凶不现", "龙登于云，垂尾之卷，下人式瞻", "垂尾之卷，终可卬也", "龙升到云上还垂下尾巴——居高不忘下面，众人都仰望他。")), "却就是退。日月有进退才有晦明，寒暑有进退才有万物生长，君子懂得进退功名才显。"),
        Ming("510", "庸", "庸，常也。日月运行，不差旦暮；四时变化，不愆寒暑；君能上下不失其尊，圣贤达节不乱其经", "土", "", mapOf("初" to PosInfo("吉凶不现", "天地之德，变化无极，四时不忒", "变化无极，终有常也", "天地变化无穷，四季却从不乱——变化再多，背后有不变的常道。"), "二" to PosInfo("臧", "井泉之渫，汲者不绝", "井泉之渫，常可久也", "井水常淘常清，打水的人不断——守住「常」，才能长久。"), "三" to PosInfo("吉", "岳镇之巍，无增无亏", "岳镇之巍，善保常也", "大山稳稳立着，不增不减——守常持重，稳如泰山。"), "四" to PosInfo("凶", "树杨沃水，一日十徙", "一日十徙，不能以荣也", "栽棵杨树一天挪十个地方，浇再多水也活不了——朝令夕改，成不了事。"), "五" to PosInfo("平", "昼作夜息，寒耕暑织，小人其职", "小人其职，君子治也", "白天干活晚上歇息、寒来耕种暑来织布——各守常职，就是平正的生活。"), "六" to PosInfo("否", "井污而久，虫幕其口", "井污而久，不知变也", "井水脏了也不淘，久了虫子都把井口封住——死守不变，反被污垢困死。"), "上" to PosInfo("吉凶不现", "鱼跳失水，困于蝼蚁", "鱼跳失水，不安常也", "鱼不安于水、跳出水面，反被蝼蚁困住——不安分守常，自取其困。")), "庸就是平常不变。日月运行不差早晚，四季变化不错寒暑；君主不失尊位，圣贤守节不乱常道。"),
        Ming("56", "妥", "妥，静也，息也。日息于夜，月息于晦，鸟兽息于蛰，草木息于根。为此者谁？曰天地。天地犹有所息，而况于人乎？", "水", "", mapOf("初" to PosInfo("吉凶不现", "藏心于虚，非有非无，其乐于于", "藏心于虚，不假物也", "把心放在虚空里，不计较有无，快乐自足——不靠外物得来的乐。"), "二" to PosInfo("吉", "止水之清，鉴物而明", "鉴物而明，得所止也", "水静下来才清澈、才照得见东西——心静下来，才看得清明。"), "三" to PosInfo("凶", "穷渎之腐，众恶攸聚", "穷渎之腐，不能择居也", "死水沟又臭又腐，什么脏东西都往这聚——居处不自洁，必招秽恶。"), "四" to PosInfo("臧", "驯鹿笼鹦，由习得成", "由习得成，制而心也", "野鹿、鹦鹉被驯服，靠的是慢慢调教——习以为常，心就安定。"), "五" to PosInfo("平", "居则郁郁，动则愈屈，吉人之得，躁人之失", "吉人之得，静以待也", "静着养气反郁郁而充实，躁动乱闯反而受挫——静是吉人的得，躁是躁人的失。"), "六" to PosInfo("否", "（鸟邑）匐于泥，不能鸣蜚", "（鸟邑）匐于泥，志在污也", "鸟甘愿趴在泥里，飞不了也鸣不了——志向陷在污秽里，自甘堕落。"), "上" to PosInfo("吉凶不现", "雷伏于地，或震于天，火伏于灰，或燎于原", "雷震火燎，因时势也", "雷伏地里终会震天，火藏灰里终会燎原——静极而动，蓄势待发。")), "妥就是静、是休。日落于夜，月休于晦，鸟兽蛰伏休息，草木归根休息；这是天地之道，天地都要休息，何况人呢？"),
        Ming("22", "蠢", "蠢，动也。天之动，昼夜以行；地之动，草木以生；圣贤之动，功业以成", "火", "", mapOf("初" to PosInfo("吉凶不现", "阳气潜萌，品汇咸生，充牣乾坤", "阳气潜萌，动在中也", "阳气在地下悄悄萌动，万物开始滋生——动从内部萌发，是生机之始。"), "二" to PosInfo("平", "新居之徙，旧居之弃，不如其已", "新居之徙，未有利也", "刚搬新居又丢下旧居，两头都没落着——动得太急，反没好处。"), "三" to PosInfo("凶", "狙入于冈，跳梁仆仰", "狙入于冈，躁益缠也", "像猴子进了山岗乱蹦乱跳，越躁动越被缠住——躁动招祸。"), "四" to PosInfo("臧", "据于蒺藜，欲去何之，不去何为？去或得岐", "虽无所之，不可处也", "坐在蒺藜刺上，走也不是不走也不是——动不得又呆不住，不如冒险找条出路。"), "五" to PosInfo("否", "凿冻树稷，劳而无得", "凿冻树稷，徙自勤也", "在冻土上凿坑种庄稼，白费力气一无所获——时机不对，动也白动。"), "六" to PosInfo("吉", "树谷于雨，拔草于暑", "树谷于雨，贵及辰也", "下雨就种谷、暑天就除草——动在节骨眼上，事半功倍。"), "上" to PosInfo("吉凶不现", "洗心藏密，龙蛇其蛰，利用无极", "龙蛇之蛰，以存神也", "洗去杂念、深藏不露，像龙蛇冬眠——动极当静，养精蓄锐。")), "蠢就是动。天动而昼夜运行，地动而草木生长，圣贤行动而功业成就。"),
        Ming("23", "讱", "讱，仁也。天地好生，秋不先春；王者尚恩，德先于刑；人无恻隐，虎狼奚异？扩而充之，同仁一视", "木", "", mapOf("初" to PosInfo("吉凶不现", "牵牛衅钟，恻于厥心", "牵牛恻心，仁之祖也", "见牛要被杀来祭钟，心里不忍——恻隐之心，是仁的源头。"), "二" to PosInfo("凶", "养虺纵蝗，匪仁之方", "养虺纵蝗，失所与也", "养毒蛇、放纵蝗虫，看着慈悲实际害人——仁用错了对象。"), "三" to PosInfo("平", "工不逾闎，车成轹辙", "工不逾闎，冥中度也", "工匠照着门框做活不出格，车造好自有辙印——仁也要有规矩尺度。"), "四" to PosInfo("臧", "青銎白刃，利以征乱", "青銎白刃，断以义也", "钢刀利刃用来平定祸乱——该出手时出手，以义断事。"), "五" to PosInfo("吉", "赤子在谷，丈人濡足", "赤子在谷，濡不避也", "孩子掉进山谷，长者顾不上湿脚就去救——发自本心的仁，不顾自己。"), "六" to PosInfo("否", "推舆济人，不如杠梁之成", "推舆济人，惠不大也", "帮人推一下车，不如修座桥——小恩小惠，不如做成大仁大义的事。"), "上" to PosInfo("吉凶不现", "至德如春，浃于无垠，莫知其然", "仁道大成，物遂也", "最高的仁像春风一样，润泽万物无边无际，谁也没觉得——仁到极致，自然天成。")), "讱就是仁。天地好生，秋不抢在春前；王者崇尚恩德，德先于刑；人若没有恻隐之心，和虎狼有什么两样？把它扩充开，就能对万物一视同仁。"),
        Ming("24", "宜", "宜，义也。君子有义，利以制事；事无常时，务在得宜；知宜而通，惟义之功。暗宜而执，亦义之贼。所以天地当就不废肃杀，圣人用刑不害慈爱", "金", "", mapOf("初" to PosInfo("吉凶不现", "盗跖庄𫏋，讳闻其恶", "跖𫏋讳恶，有羞恶也", "连盗跖这种大盗都怕听自己的恶名——人天生有羞耻心，义从这来。"), "二" to PosInfo("否", "守尔庖鱼，丧尔囊珠，匪愚则迂", "丧尔囊珠，所失大也", "死守着一条小鱼，丢了整袋明珠——因小失大，不是蠢就是迂。"), "三" to PosInfo("凶", "徇利遗节，托名以说，污于斧钺", "托名以说，以欺世也", "为利丢掉气节，还要拿好名声来辩解——欺世盗名，早晚污于刀斧。"), "四" to PosInfo("吉", "名驹大辂，安行正路，疾徐中度", "疾徐中度，不失节也", "名马大车走在正路上，快慢都合规矩——守义而行，走得安稳。"), "五" to PosInfo("平", "李傕杀身，无所成名", "李傕杀身，不可为名也", "李傕想靠杀人成名，结果身败名裂——义不是靠恶名求来的。"), "六" to PosInfo("臧", "断臂纳肚，毁形残生，惟心所安", "毁形残生，义无咎也", "为了义，断了臂、伤了身也心甘——心之所安，形残无咎。"), "上" to PosInfo("吉凶不现", "徇义之大，手足无爱", "手足无爱，大得宜也", "真正的大义面前，连手足都可以舍弃——义到极处，舍身取义。")), "宜就是义。君子守义来处事；事情没有固定的时候，重在做得合宜；懂得合宜而通达，是义的功劳；不明合宜而固执，是义的祸害。"),
        Ming("25", "忱", "忱，信也。天地信而岁功成，日月信而历象明，人君信而号令行，人臣信而邦家荣。苟为舍之，未见其能久长者也", "土", "", mapOf("初" to PosInfo("吉凶不现", "可用交，勿恤。其孚后有徒", "勿恤其孚，自诚也", "可以放心交往，不必多虑——只要自己诚，诚信后面自然有人跟。"), "二" to PosInfo("臧", "言无夸善，惧不能践", "言无夸善，省华求实也", "说话不吹嘘，怕的就是许了诺做不到——省掉浮华，求个实在。"), "三" to PosInfo("吉", "天道难测，四时不忒，下土之式", "下土之式，人信之也", "天意难测，四季却从不失信——天地守信，所以天下都信它。"), "四" to PosInfo("凶", "父子乖离，吐心而疑，祸不在辜", "父子乖离，不知其可也", "连父子都离心，掏出真心还被怀疑——失了信，祸根已经埋下。"), "五" to PosInfo("平", "硁硁之信，小夫之谨", "小夫之谨，可为民也", "死守一句小承诺，是小人物的本分——虽不大，却不失为可靠。"), "六" to PosInfo("否", "小信之必，大义之失，君子不由", "君子不由，轻重权也", "为了守住小信，丢了真正的大义——君子不这么干，懂得权衡轻重。"), "上" to PosInfo("吉凶不现", "坚城捍外，强堤遏水，革囊浮海，漏不在大", "城堤浮囊，不可不完也", "城墙、堤坝、皮囊，能守住全靠无漏——信也一样，破绽往往在小处，要处处周密。")), "忱就是信。天地守信岁功才成，日月守信历法才明，君主守信号令才行，臣子守信国家才荣；舍弃诚信，难以长久。"),
        Ming("26", "喆", "喆，智也。经天纬地，必有其理。智者见之，心闲事济，凿不为巧诈，以为奸。圣门论智，其说不然。", "水", "", mapOf("初" to PosInfo("吉凶不现", "益薪火发，涤秽泉冽", "益薪涤秽，务学袪蔽也", "添柴火才旺、淘洗泉才清——不断学习，才能祛除蒙蔽。"), "二" to PosInfo("吉", "斤斧颙颙，梓匠之从", "梓匠之从，小役大也", "斧头凿子都备齐，工匠都听你调遣——有智有具，大事可成。"), "三" to PosInfo("凶", "盗兵利吏，不制", "盗兵利祇，益害也", "把兵器交给强盗、把权力交给奸吏，不加管束——反而助长祸害。"), "四" to PosInfo("臧", "动若流水，惟物之利", "流水之动，以利物也", "行动像流水一样顺势而变，处处利人利物——智慧在于因势利导。"), "五" to PosInfo("平", "务本安分，金玉其命", "务本安分，知保身也", "守本分、务正业，命贵如金玉——智者懂得安身保命。"), "六" to PosInfo("否", "狙鼠狡谲，志在窃食", "狙鼠狡谲，以窃食也", "像猴子老鼠那样耍小聪明，只为偷口吃的——智用歪了，反成窃贼。"), "上" to PosInfo("吉凶不现", "神禹浚川，行其自然", "行其自然，不为凿也", "大禹治水是顺着水性疏导，不是硬凿——大智在顺天应人，不耍机巧。")), "喆就是智慧。治理天下必有道理；智者看清道理，从容而成事，不靠机巧诈伪。"),
        Ming("27", "戛", "戛，礼也。天高地下，制礼之经；尊隆卑杀，饰礼之文。人不知礼，进退无度，手足冈措；国不用礼，纪纲不举，四邻之侮", "火", "", mapOf("初" to PosInfo("吉凶不现", "仰天俯地，正名辨位，以定民志", "仰天俯地，名位判也", "抬头看天、低头看地，把名分位置摆正，民心才安定——礼从天地来。"), "二" to PosInfo("平", "敝衣蔽形，犹愈裸裎", "敝衣蔽形，犹愈无也", "破衣服好歹遮住身体，比光着强——礼再简陋，也比没有强。"), "三" to PosInfo("凶", "衣冠周孔，揖逊发冢", "揖逊发冢，以饰奸也", "穿着圣人的衣冠、装得彬彬有礼，干的却是盗墓的勾当——礼成了奸人的伪装。"), "四" to PosInfo("臧", "掣牛之狂，服亩遵场", "掣牛之狂，能自制也", "再野的牛，套上缰绳也能老实耕地——礼就是约束野性、归于正道。"), "五" to PosInfo("否", "偶人粉泽", "偶人粉泽，徒饰外也", "木头人涂脂抹粉，光有外表——礼只做表面功夫，就是空架子。"), "六" to PosInfo("吉", "斐如煌如，纪如纲如，四海王如", "斐如煌如，王者事也", "礼文斐然、纲纪煌煌，四海归于一统——礼行天下，是王者的事业。"), "上" to PosInfo("吉凶不现", "男女贵辨，嫂溺则援", "嫂溺则援，礼有权也", "礼讲男女有别，可嫂子落水还是要伸手救——礼有变通，紧要处从权。")), "戛就是礼。天高地下是礼的根本，尊卑有别是礼的仪文；人不知礼进退无度手足无措；国不用礼纲纪不振，招四邻欺侮。"),
        Ming("78", "特", "特，夫也。天气下降，地资以生；日光旁烛，月借以明。夫和而正，妇听以行，是谓天地之终也，是谓天地之终，阴阳之义，人道之始。", "木", "", mapOf("初" to PosInfo("吉凶不现", "桃李之衰，情怿心悲，松筠之思", "松筠之思，晚无及也", "桃李凋谢才想起松柏长青——早没想到，到晚了来不及。"), "二" to PosInfo("凶", "有豭在牢，或投之刀，先笑和后号", "先笑后号，不永终也", "猪在圈里还乐着，转眼刀就下来——先头高兴，后头哭，好景不长。"), "三" to PosInfo("平", "夫刚而令，妇顺而听", "夫刚妇顺，未失常也", "丈夫刚正面有威，妻子柔顺而听从——夫唱妇随，没失常道。"), "四" to PosInfo("臧", "闺门雍穆，靡歌靡哭", "靡歌靡哭，得中节也", "家门之内雍容和睦，不喧歌不悲哭——夫妻之道，贵在中和有节。"), "五" to PosInfo("吉", "德礼不贰，舜嫔妫汭", "德礼不贰，以身先也", "德行礼义始终如一，像舜以德相感而婚——以德为先，夫妻大吉。"), "六" to PosInfo("否", "铅刀析薪，折齿馀龂", "折齿馀龂，不可用制也", "用铅做的刀去砍柴，一砍就崩口——丈夫没了刚劲，担不起事。"), "上" to PosInfo("吉凶不现", "枯杨生华，老夫得其女；妃蛇入燕巢，惟雏之悲", "枯杨生华，何可久也？蛇入燕巢，必败家也", "枯杨开花、老夫娶少妻，像蛇钻进燕窝——违背常理，必败家。")), "特就是夫。天气下降地借以生，日光普照月借以明；夫温和端正，妇听从而行，这是阴阳之义、人道的开始。"),
        Ming("79", "偶", "偶，妃也。天能始事，地实终之；阳能生物，阴实成之。有夫无妇，中馈孰主？所以咸先于恒，男下于女", "金", "", mapOf("初" to PosInfo("吉凶不现", "嗜酒之甘，不知沈酣；虺蛇是长，末或成蟒；", "末或成蟒，不早辨也", "贪杯不觉醉、养蛇不防它长大成蟒——坏毛病从小纵容，早晚成大祸。"), "二" to PosInfo("否", "忌疾贪鄙，徇情黜理", "徇情黜理，不服训也", "又嫉妒又贪婪，凭个人喜好废了道理——听不进规劝。"), "三" to PosInfo("凶", "牝鸡司晨，惟家之索", "牝鸡司震，反常也", "母鸡打鸣、妇人当家做主——阴阳颠倒反常，家道要衰。"), "四" to PosInfo("吉", "坠柔而静，品物咸正", "坠柔而静，顺承天也", "柔顺安静、顺承天道——妇道如此，万物归正。"), "五" to PosInfo("平", "无非无仪，中馈攸司", "中馈攸司，未失道也", "不挑错不生非，把家事料理好——安分守己，未失妇道。"), "六" to PosInfo("臧", "康王晏起，妾后请罪", "姜后之请，警戒相成也", "康王睡懒觉，王后自责规劝——贤内助的规劝，夫妇相成。"), "上" to PosInfo("吉凶不现", "君王后治齐，不可用正，吕武用口", "不可用正，妇有从子也", "女主当权治国，终究名不正言不顺——妇人终究要从于子，不宜专权。")), "偶就是妇。天创始事物，地完成事物；阳生发万物，阴成就万物；有夫无妇，家中谁主中馈？所以男下于女，夫唱妇随。"),
        Ming("710", "昵", "昵，亲也。疏者必疏，亲者必亲，事之常理，人之常情。苟违其常，心安查怙，识者畏之，如避豺虎", "土", "", mapOf("初" to PosInfo("吉凶不现", "九族咸序，省躬之故", "省躬之故，知所从也", "九族都井然有序，靠的是时时反省自己——亲亲先从修身开始。"), "二" to PosInfo("臧", "象封有庳，食而弗治", "食而弗治，弗私以政也", "舜封弟弟象一块地，只给衣食不给实权——亲归亲，不因私废公。"), "三" to PosInfo("吉", "竹枯不拔，蚿死不蹶", "竹蚿之安，辅之多也", "竹子枯了不拔、虫子死了不绊——根基稳固，靠的是平时辅助多、根基厚。"), "四" to PosInfo("凶", "条亡枾存，或斧之根", "条亡枾存，见者执柯也", "枝叶没了、树干还在，可有人来砍树根——亲缘败落，根基也难保。"), "五" to PosInfo("平", "父母妻属，等衰以睦", "等衰以睦，示不同也", "父母、妻儿按亲疏远近分出次序来和睦相处——亲也有等差，才不乱。"), "六" to PosInfo("否", "割臂斮足，易之金玉，其肌不属", "割臂易玉，弃亲即它也；其肌不属，人于汝何也", "割自己的手臂去换金玉——为了外物抛弃骨肉至亲，别人还怎么认你。"), "上" to PosInfo("吉凶不现", "尧舜亲亲，万国兴仁", "万国兴仁，大成仁也", "尧舜亲近亲族、推己及人，天下都兴起仁德——亲亲做到极致，就是大仁。")), "昵就是亲近。该疏的疏、该亲的亲，是常理常情；违背常理还心安理得，明白人见了避之如避豺虎。"),
        Ming("71", "续", "续，子也。尧父舜子，二者难全，与其父智，宁若子贤。所以舜生商均，虞祚不延，鲧生神禹，祀夏配天", "水", "", mapOf("初" to PosInfo("吉凶不现", "络马首，穿牛鼻，利用以早", "络马穿牛，幼易驯也", "马早套笼头、牛早穿鼻环才好驯——教育孩子要趁早。"), "二" to PosInfo("吉", "父墢其土，子终厥亩", "子终厥亩，能绍先也", "父亲开好的地，儿子接着种完——子承父业，能续前人。"), "三" to PosInfo("凶", "鲎子满腹，不如蜾裸之不育", "鲎子满腹，害厥生也", "鲎虫一肚子都是祸害自己的东西，不如蜾蠃宁可不育——养出祸害，不如不生。"), "四" to PosInfo("臧", "饭菽羹藜，父母怡怡", "父母怡怡，善承意也", "吃粗粮野菜，父母也高高兴兴——孝顺贵在顺意，不在厚养。"), "五" to PosInfo("平", "鹰雏匪鸾，不为鸱鸢", "不为鸱鸢，亦似宗也", "孩子虽不是凤凰，却也不沦为恶鸟——像祖上的样子，就算不辱门风。"), "六" to PosInfo("否", "酒膳纷如，父母频如", "父母频如，不养志也", "酒肉摆满桌，父母却频频叹气——光供吃喝不养心志，白养了。"), "上" to PosInfo("吉凶不现", "体完不隳，德备不亏，祖考之晖", "体完德备，终子事也", "身体康全、德行无亏，把祖上的光辉传下去——这是做儿子最圆满的收尾。")), "续就是子嗣。尧父舜子难两全，与其父有智慧，不如子有贤德；舜生商均没保住虞朝，鲧生大禹却配天享祀。"),
        Ming("77", "考", "考，父也。君为尊矣，患于不亲；母为亲矣，患于不尊；能尽二者，其惟父乎？慈而不训，失尊之义；训而不慈，害亲之理。慈训曲全，尊亲斯备", "火", "", mapOf("初" to PosInfo("吉凶不现", "老牛舐犊，不如燕引其雏", "燕引其雏，教之飞也", "老牛只会舔小牛，不如燕子教雏燕学飞——疼爱要落在教导上。"), "二" to PosInfo("平", "作室无资，勿坏其基，以俟能为", "作室无资，不可强也。勿坏其基，亦可尚也", "盖房的钱不够，别把地基糟蹋了，等有能力的人来接手——留好根基就是功。"), "三" to PosInfo("凶", "爱马益粟，肥溢而陆，终不可服，或授之槊", "爱马益粟，祗益害也", "太宠马，喂太肥反而不能骑、还被人刺——溺爱过头，反成祸害。"), "四" to PosInfo("臧", "散而金珠，聚而诗画，贤不丧志，否不益愚", "散而金珠，贤于人也", "把金珠散掉、把诗画聚起来——贤者不因富贵丧志，也不因困厄变蠢。"), "五" to PosInfo("否", "囊金匣玉，不畀之烛，盗守之屋", "不畀之烛，失义诲也", "金玉满箱却不教孩子辨明暗，等于让贼守着自己的屋子——富而不教，招祸。"), "六" to PosInfo("吉", "薪火不灭，贻汝圣喆，锡汝圭槷，无疆之庆", "薪火不灭，明有继也", "薪火相传不熄，把智慧美德传给孩子，是无边的福庆——后继有人。"), "上" to PosInfo("吉凶不现", "丹朱商均，利用作宾", "利用作宾，知子明也", "尧舜明知儿子不堪大任，就让他们做个宾客——知子之明，不为私情误国。")), "考就是父。君尊而难亲近，母亲而难尊崇；能两全的只有父亲。只慈爱不教导有失尊义，只教导不慈爱有伤亲情；慈爱教导两全，尊与亲才兼备。"),
        Ming("58", "范", "范，师也。天垂日星，圣人象之；地出图书，圣人则之；渔叟之微，文武是资；郯子之陋，孔子所咨。若之，何其无师？", "木", "", mapOf("初" to PosInfo("吉凶不现", "易子之义，责善是为，惟严之利", "惟严之利，人知畏也", "古人换着教孩子，就是为了下得了严手——严格，师道之始。"), "二" to PosInfo("凶", "衡不平绳，不直大㪷短尺民莫之则", "衡不平，不足由也", "秤不平、绳不直、大斗短尺，百姓没法遵循——为师者自己不正，何以教人。"), "三" to PosInfo("平", "章句之见，授其训传，以钥投键", "以钥投键，发蒙也", "教章句、传训诂，像钥匙对锁——启人之蒙，方法要对。"), "四" to PosInfo("臧", "北指燕，南指楚，惟尔之取", "北燕南楚，使自谋也", "告诉学生哪是燕哪是楚，让他自己走——教的是方向，路要自己选。"), "五" to PosInfo("吉", "准矩绳规，众法攸资", "准矩绳规，先自修也", "自己先立好规矩准绳，众人才有所取法——为师先正己。"), "六" to PosInfo("否", "投壁于暗，或按之釰", "投璧于暗，人不见也", "把美玉扔进黑暗里，没人看得见——有才不教、藏而不露，等于白费。"), "上" to PosInfo("吉凶不现", "圣作六经，万世典型，如见其人", "万世典型，言作训也", "圣人写下六经，万世都拿它作典范——师道大成，泽被后世。")), "范就是师。天垂日月星辰圣人效法，地出河图洛书圣人取则；打渔老翁的微言，文王武王都要借鉴；郯子的浅见，孔子还去请教。人怎么能没有老师？"),
        Ming("44", "徒", "徒，众也。薪以续火，益之愈光；江汉承流，达于遐方；颜闵传业，圣道以彰。", "金", "", mapOf("初" to PosInfo("吉凶不现", "出门择术，跬步之失，之晋而粤", "出门择术，慎所从也", "出门先选对路，一步走错就从山西跑到广东——跟什么人、学什么术，起步就要慎。"), "二" to PosInfo("否", "巧心妙手，木不雕朽", "木不雕朽，其质陋也", "心思再巧，朽木也雕不出东西——材质太差，徒众再多也没用。"), "三" to PosInfo("凶", "虎豹之能，千人莫当，不可服箱", "不可服箱，不可训也", "虎豹再凶猛，千人挡不住，可让它拉车驯服它——有才不受驯，反成祸。"), "四" to PosInfo("吉", "骅骝骐骥，造父授辔，一日千里", "一日千里，天才异也", "千里马遇上好驭手，一日千里——人才遇明师，天才方能尽展。"), "五" to PosInfo("平", "中人不惰，可以寡过", "中人不惰，志务学也", "天资一般但不偷懒，就能少犯错——勤能补拙，学可进德。"), "六" to PosInfo("臧", "樛木之曲，惟材之辱，为轮转毂", "曲木为轮，性可揉也", "弯木头经火烤水揉，也能做成车轮——材质可塑，只要肯下功夫调教。"), "上" to PosInfo("吉凶不现", "仲尼之道，三传不替，以克永世", "以克永世，道大明也", "孔子之道传了几代都不断绝——真正的道，靠传承而永世光明。")), "徒就是众多。柴续火越添越亮，江汉承流到达远方，颜回闵损传承学业，圣人之道得以显扬。"),
        Ming("45", "丑", "丑，友也。天地相友，万汇以生；日月相友，群伦以明；风雨相友，草木以荣；君子相友，道德以成。", "土", "", mapOf("初" to PosInfo("吉凶不现", "素丝缟如，适缁适朱", "适缁适朱，惟所择也", "白丝染黑染红，全看染料——交友如染色，跟谁就变谁。"), "二" to PosInfo("臧", "意气相许，不以利取", "取不以利，能择交也", "交朋友凭意气相投，不图利益——这才是会择交。"), "三" to PosInfo("吉", "水石相亲，石洁水清；蓬麻共植，惟蓬亦直", "惟蓬亦直，近贤也", "蓬草长在麻地里也能长直——跟好人在一起，自己也会变好。"), "四" to PosInfo("凶", "总角绸缪，胶而漆投；半途分流，注矢操矛", "注矢操矛，反相贼也", "小时候好得如胶似漆，半路翻脸，拔箭持矛相向——交情不固，反成仇敌。"), "五" to PosInfo("平", "春耕秋获，易力并作，游惰勿诺", "游惰勿诺，不如己也", "春种秋收要一起出力——游手好闲的人，别答应跟他合伙。"), "六" to PosInfo("否", "毛群羽聚，粮食之蠹", "粮食之蠹，无所益也", "一群乌合之众聚在一起，只会消耗粮食——无益之交，不如不交。"), "上" to PosInfo("吉凶不现", "一首三尾，先完后毁，惟初之罪", "惟初之罪，不早识也", "一个头三条尾，开头圆满后来全毁——错就错在起初没看清人。")), "丑就是朋友。天地相配万物生，日月相配伦常明，风雨相济草木荣，君子交友道德成。"),
        Ming("46", "隶", "隶，臣也。地不天不能以生，月不日不能以光，臣不君不能以功", "水", "", mapOf("初" to PosInfo("吉凶不现", "木养其材，工则剫之；玉潜于石，人则琢之", "木养其材，以待用也", "树木养好自己的材质等工匠来取，美玉藏在石里等人来琢——臣子先修己以待用。"), "二" to PosInfo("吉", "玉马金牛，惟邦之宝", "玉马金牛，专所奉也", "玉马金牛，都是国家的宝贝——贤臣是邦国之宝，要专心奉养。"), "三" to PosInfo("凶", "一身三首，蜂蚁所丑", "一身三首，无所容也", "一个身子三个头，连蜂蚁都嫌弃——三心二意、多头领导，无处容身。"), "四" to PosInfo("臧", "登丘而俛，置膝而远，百录简简。", "登丘而俛，不自崇也", "登上山丘却低头俯看、把功绩放低——不自居功，臣德之美。"), "五" to PosInfo("平", "股肱缀体，没世不改", "股肱不改，知所从也", "臣子像大腿胳膊长在身上，终身不变——忠于所事，矢志不移。"), "六" to PosInfo("否", "颜载其劳，口扬其高，挟恩以骄，或倳之刀", "或倳之刀，怙其庸也", "满脸是功、满口自夸，挟恩自傲——这种臣子，早晚挨刀子。"), "上" to PosInfo("吉凶不现", "秋谷既收，土田之休", "谷收田休，不敢处功也", "秋收完了让田地歇着——功成身退，不占功劳，臣道之善。")), "隶就是臣。地离了天不能生养，月离了日不能发光，臣离了君不能建功。"),
        Ming("47", "林", "林，君也。三人无主，不能共处；一人元良，万国以康。厥德惟何？仁武及明，备则蕃昌，缺则衰亡。夫民之所资者，道也，不可斯须去也。是以君臣相与议于朝，师友相与讲于野，然后道存而国可治也", "火", "", mapOf("初" to PosInfo("吉凶不现", "赤子之命，在厥初生", "赤子初生，性命系也", "婴儿一生的根基在初生之时——为君之初，奠基最重要。"), "二" to PosInfo("平", "循迹不失，无丧无得", "循迹不失，亦足继也", "踩着前人的足迹不偏离，虽无大得也无大失——守成之君，稳当即可。"), "三" to PosInfo("凶", "奸赏忠诛，臧违否依，首足颠施", "奸赏忠诛，庶事戾也", "奖赏奸邪、诛杀忠良，是非颠倒、头脚倒置——国政全乱了。"), "四" to PosInfo("臧", "巨舟峨峨，济于洪波", "巨舟峨峨，赖贤以济也", "大船能渡惊涛骇浪，靠的是船上的贤才——为君赖贤以济。"), "五" to PosInfo("否", "鉴无光斧，无铓股肱，不从，惟身之殃", "光铓之无，下不使也", "镜子不明、斧头没刃，臣下都不听使唤——为君无威无明，自身遭殃。"), "六" to PosInfo("吉", "天日昭昭，如榱柱森，如忠进奸，诛", "天日昭如，明无蔽也", "天日昭昭，忠臣进、奸佞诛——为君至明，天下肃然。"), "上" to PosInfo("吉凶不现", "日中而移，山高而危，大人克终", "日中而移，不可不戒也", "太阳到顶就要偏、山到最高就危险——为君鼎盛之时，更要警惕善终。")), "林就是君。三人没个主事的一起不成事；一人贤良，万国安康。他的德行是什么？仁、武、明，具备则昌盛，缺失则衰亡。"),
        Ming("48", "禋", "禋，祀也。豺知祭兽，獭知祭鱼；忘先背本，傲忽狂愚；明而人责，幽则鬼诛", "木", "", mapOf("初" to PosInfo("吉凶不现", "圣人知幽，明之故。死生之说，鬼神之情状", "祭祀之设，非虚文也", "圣人明白幽冥与显明的道理、知道生死的由来——祭祀不是走形式。"), "二" to PosInfo("凶", "谓祖无知，谓天可欺，谓祭何为", "谓祭何为，心傲忽也", "以为祖先没知觉、老天可欺瞒，祭祀还有什么用——心太傲慢轻忽。"), "三" to PosInfo("平", "豺獭之鉴，霜露之思，无失其时", "无失其时，不忘本也", "豺獭尚且知道祭天祭兽，人逢霜露之节更该思亲——按时祭祀，是不忘本。"), "四" to PosInfo("臧", "匪隆匪杀，惟义所在", "惟义所在，务适宜也", "祭祀不铺张也不寒酸，一切以合宜为准——祭以诚义为本。"), "五" to PosInfo("吉", "茧粟之角，瓦登匏爵，上帝是享", "茧粟之角，诚不必丰也", "哪怕只有小牛角、瓦盆葫芦杯，诚心到了上帝也领——祭贵在诚，不在丰。"), "六" to PosInfo("否", "弗播而谷，弗攻而木，祀淫祭黩", "祀淫祭黩，佞神也", "不种地想收谷、不砍树想要木料，一味求神拜鬼——这是谄媚鬼神，不是祭祀。"), "上" to PosInfo("吉凶不现", "学匪干禄，祭匪求福，果时则熟", "果时则熟，理必至也", "读书不为求官、祭祀不为求福——该熟的自然会熟，道理到了自然有成。")), "禋就是祭祀。豺都知道祭兽，獭都知道祭鱼；忘祖背本、傲慢昏愚，明处被人指责，暗处遭鬼神之诛。"),
        Ming("49", "准", "准，法也。为农无法，黍稷不生；为工无法，器用不成；用众无法，资敌丧兵；治国无法，长乱殃民", "金", "", mapOf("初" to PosInfo("吉凶不现", "堇茶之萌，薙则不荣；燎火荧荧，沃不尽瓶", "堇茶之萌，恶不可恣也", "毒草一冒芽就得锄，火星一闪就得浇——坏事要掐死在开头。"), "二" to PosInfo("否", "瞽夫执铚，兰艾同制；上冈下毕，兽骇而突", "兽骇而突，穷则悖也", "瞎子收割，香草臭草一锅端；把野兽逼急了它也会反扑——法度混乱，必生悖乱。"), "三" to PosInfo("凶", "罔密而敝，鰴逃鮂系，不如其弃", "鰴逃鮂系，制小失大也", "网眼织得太密又太破，大鱼跑了、小鱼被困死——法太苛太乱，抓小失大。"), "四" to PosInfo("吉", "禽虎于穴，百兽战栗，冈目甚阔，冒不可脱", "禽虎于穴，慑暴类也", "老虎被关进笼子，百兽都服帖——法能制暴，天下自安。"), "五" to PosInfo("平", "盘水之盈，小偏必倾；庭燎之明，继其薪蒸", "盘水之盈，偏则败也；庭燎继薪，明不可怠也", "满盘水稍一偏就洒；火炬要不断添柴才亮——执法要公平如盘水、持久如续薪。"), "六" to PosInfo("臧", "稂莠之锄，嘉谷扶疏", "稂莠之锄，去物害也", "把稗草锄掉，好谷才长得茂盛——法除害物，良善自生。"), "上" to PosInfo("吉凶不现", "驱蝇去饭，毋使污案，逐之勿远", "驱蝇去饭，不足追罪也", "苍蝇飞进饭里，赶走就行，别追出十里地——执法也要有分寸，勿苛勿滥。")), "准就是法度。种田无法五谷不生，做工无法器物不成，用兵无法资敌丧师，治国无法祸乱殃民。"),
        Ming("910", "资", "资，用也。何以临人曰位，何以聚民曰财。有位无财，斯民不来。所以洪范八政，食货惟先；天子四民，农商居半", "土", "", mapOf("初" to PosInfo("吉凶不现", "衣食货赂，生养之具，争怨之府", "争怨之府，当义治也", "衣食钱财是养命的东西，也是争吵怨恨的源头——要用道义来管。"), "二" to PosInfo("臧", "子羸父单，不忧饥寒", "子羸父单，厚于民也。不忧饥寒，必相养也", "孩子弱、父亲单，但日子不愁饥寒——藏富于民、上下相养，才算善用。"), "三" to PosInfo("吉", "务其耕桑，尊农卑商；疏原道委，上下均利", "尊农卑商，明本末也；疏原道委，通上下也", "重农桑、轻商贾，把水路财源疏通，上下利益均沾——用财得法，国富民安。"), "四" to PosInfo("凶", "山童泽涸，今笑后哭", "山童泽涸，其利穷也", "山砍秃了、水抽干了，眼前得意，日后哭都来不及——竭泽而渔。"), "五" to PosInfo("平", "璞随之富，或兴或仆", "或兴或仆，道不同也", "像随侯珠那样的财富，有人因此兴旺有人因此败落——财本身无吉凶，看怎么用。"), "六" to PosInfo("否", "大盈藏金，鄙夫之心", "鄙夫之心，私积财也", "拼命囤金藏银、只进不出——那是鄙陋小人的心思，财聚而人不聚。"), "上" to PosInfo("吉凶不现", "勤约成风，人不困穷", "勤约成风，身先之也", "从上到下勤俭成风，百姓就不困穷——带头节俭，是最好的用财。")), "资就是资用。凭什么治理人？靠位；凭什么聚拢民？靠财。有位无财，民众不来。所以《洪范》八政食货优先，农商各居其半。"),
        Ming("91", "宾", "宾，客也。君臣燕饮，有主有宾；诸侯朝聘，天子之宾；四夷朝贡，中国之宾。所以周官设行人之职，行苇歌序宾之礼", "水", "", mapOf("初" to PosInfo("吉凶不现", "宾择主人，有礼则亲", "宾择有礼，主宜谨也", "客人也要挑主人，主人有礼才亲近——交往先看对方是否以礼相待。"), "二" to PosInfo("吉", "三十辐共一毂，天子雍雍，四明穆穆", "四门穆穆，无离心也", "三十根辐条共着一个车毂，四方来朝、和穆无间——广纳宾客，人心归一。"), "三" to PosInfo("凶", "薉其涂拒，其户四邻攻之，莫之或助", "薉涂拒户，不与物交也", "把路堵脏、把门关上，四邻来攻都没人帮你——闭门拒客，自绝于人。"), "四" to PosInfo("臧", "重礼轻币，远人毕至", "重礼轻币，不为利也", "重情礼、轻财帛，远方的人都愿意来——待客以诚，不以利诱。"), "五" to PosInfo("平", "伯父伯舅，惟宾惟友，礼循其旧", "礼循其旧，国有制也", "对伯父伯舅也待以宾友之礼、不破旧章——礼有定制，尊卑有序。"), "六" to PosInfo("否", "秦帝按剑，诸侯西驰，面服心违", "面服心违，威劫之也", "靠武力威压，诸侯表面归服、心里不服——以威劫客，终难长久。"), "上" to PosInfo("吉凶不现", "东邻无客，西邻之集", "西邻之集，亦可畏也", "东家冷冷清清没客人，西家宾客盈门——人气流向哪里，得失一看便知。")), "宾就是客。君臣宴饮有主有宾，诸侯朝聘是天子的宾客，四夷朝贡是中国的宾客。所以周官设行人之职，行苇歌咏宾主之礼。"),
        Ming("92", "𢦦", "𢦦，兵也。天生五材，民并用之，阙一不可，孰能去兵？傥忧生乱，何以止乱？所以乐有舞干，燕必有射佩釰，即御敌之具，井田寓营陈之法", "火", "", mapOf("初" to PosInfo("吉凶不现", "不利为寇，利用御寇", "利用御寇，以自卫也", "用兵不为掠夺，只为抵御来犯——兵的本义是自卫。"), "二" to PosInfo("平", "利釰在手，不敢饮酒", "利釰在手，不敢饮酒，知戒慎也", "宝剑在手，连酒都不敢多喝——握有兵权更要戒慎，不能松懈。"), "三" to PosInfo("凶", "兵由贪忿，民殚国烬", "民殚国烬，终自焚也", "因贪念和怒火兴兵，百姓打光、国家烧尽——玩火者终自焚。"), "四" to PosInfo("臧", "节制之兵，有死无奔", "兵死不奔，有节制也", "纪律严明的军队，宁死也不溃逃——节制是兵之魂。"), "五" to PosInfo("否", "公孙建议，禁挟弓矢", "公孙之议，不穷理也", "像公孙弘建议禁百姓带弓箭——只顾禁器，不究祸乱根源，是理没穷尽。"), "六" to PosInfo("吉", "伐乱除凶，修国省躬", "修国省躬，以正人也", "讨伐祸乱、除去凶恶，回过头修明国家、反省自身——兵以正人，吉。"), "上" to PosInfo("吉凶不现", "戢戈橐矢，忧患方始", "忧患方始，戒不虞也", "仗打完了、兵器入库，忧患才刚开始——太平之时最要防患未然。")), "𢦦就是兵。天生五种材料民众都用，缺一不可，谁能废去兵？只怕生了乱，拿什么止乱？所以乐有干舞、燕饮佩剑，都是御敌之具，井田里就寓着布阵之法。"),
        Ming("93", "敩", "敩，教也。木有材，工则斲之；民有性，君则教之。生之者，天也；养之者，人也。其既成也，发育无渐，而后可以为良民。教化既美，习俗既成，运数莫夺，越千百年，风流不绝。", "木", "", mapOf("初" to PosInfo("吉凶不现", "去母从父，得其途路", "得其途路，知向方也", "离开溺爱的母亲、跟从严父，才走上正路——教育要早离娇惯、知道方向。"), "二" to PosInfo("凶", "虎狼养子，教之搏噬，秦人以毙", "秦人以毙，不由义训也", "像虎狼教幼崽搏杀，教出来的是祸害——靠残暴教人，终将自毙。"), "三" to PosInfo("平", "建其师，立其规，执其笞", "建其师，择师长也；立其规，示轨物也；执其笞，弼以刑也", "请好老师、立好规矩、必要时动戒尺——教有三件套：师、规、罚。"), "四" to PosInfo("臧", "汉光厉俗，几亡娄续", "汉光厉俗，尚名节也", "汉光武整饬风俗、崇尚名节，几乎消亡的道统又续上了——教人重名节，可挽颓风。"), "五" to PosInfo("吉", "直木不令，其影自正", "其影自正，身先之也", "树干是直的，影子不用管也正——身教胜于言教，自己正，教自然成。"), "六" to PosInfo("否", "饱食嘻嘻，禽犊之肥", "饱食嘻嘻，逸居无教也", "吃饱了就嬉闹，跟养肥的猪牛没两样——安逸无教，人就废了。"), "上" to PosInfo("吉凶不现", "契敷五教，黎民时雍，比屋可封", "比屋可封，恶人尽也", "契推行五伦之教，百姓和睦、家家可封——教化大成，人人向善。")), "敩就是教化。木有材质工匠来加工，民有本性君主来教化；生育的是天，教养的是人；教化既美、习俗既成，千百年风流不绝。"),
        Ming("99", "乂", "乂，治也。农夫治地种植，耘除；王者治国，庆赏刑诛；众而不治其国，无制；无制之国，其民作慝。", "金", "", mapOf("初" to PosInfo("吉凶不现", "刀斧椓器，先必就砺", "刀斧就砺，先自治也", "刀斧要先用磨石磨利——治理他人，先把自己打磨好。"), "二" to PosInfo("否", "政令苛碎，遗大得细，上劳下敝", "上劳下敝，不知要也", "政令太琐碎苛刻，抓了小节丢了根本，上边累死、下边疲敝——没抓住要领。"), "三" to PosInfo("凶", "卑人为主，丧其资斧", "丧其资斧，任匪人也", "让卑劣小人当家做主，连自己的家底都丢了——用错人，全盘皆输。"), "四" to PosInfo("吉", "欲冈之，张引其纲；欲丝之，治振其纪", "纲张纪举，贤愚从也", "撒网要提总纲、理丝要抓头绪——治理抓根本，上下自然跟从。"), "五" to PosInfo("平", "量形制衣，可用为仪", "量形制衣，不好大也", "量着身形裁衣，不贪大——治理要合实际，不务虚名。"), "六" to PosInfo("臧", "纲阔而疏，蝤虾其逋，利以得鱼", "利以得鱼，得民也", "网眼故意放宽，小虾小鱼放走，为的是留住大鱼——宽以得民，是大智慧。"), "上" to PosInfo("吉凶不现", "熊鱼科斗，惟萃于首", "惟萃于首，不续终也", "熊掌、鱼、蝌蚪都想占，全堆在头顶——贪多务得，终究不能善终。")), "乂就是治理。农夫治田要耕耘除草，王者治国要赏罚刑诛；人多而不治就没有制度，没有制度的国家，民众就会作恶。"),
        Ming("1010", "绩", "绩，功也。事不见功，何以为终？务学不在多，能以道成为功；用兵不在多，胜以乱静为功。是故：物成，秋冬天地之功；时底，隆平帝王之功", "土", "", mapOf("初" to PosInfo("吉凶不现", "先春布谷，虽劳不育；忍以俟时，若迟若速", "若迟若速，善乘时也", "春没到就播种，再辛苦也不发芽——做事要忍得住，等时机到了，快慢都成。"), "二" to PosInfo("臧", "帝王君臣，务在安民", "务在安民，无奇功也", "帝王君臣的大功，就是让百姓安定——平平常常的安民，就是最实在的功。"), "三" to PosInfo("吉", "六子奋庸，万物以丰，天地之功", "天地之功，不自为也", "天地生养六子、成就万物——功成而不居，才是天地般的大功。"), "四" to PosInfo("凶", "有鳣悦珠，人口之腴", "有鳣悦珠，匪其人也；人中之腴，祇取祸也", "鳣鱼贪恋明珠，反而成了人嘴里的美味——贪图虚名美利，反招杀身之祸。"), "五" to PosInfo("平", "项羽日胜而亡，高祖日败而王", "日败而王，善要终也", "项羽天天打胜仗却亡国，刘邦天天打败仗却得天下——功不在眼前胜负，在善终。"), "六" to PosInfo("否", "生事要功，利己夸庸", "生事要功，好作为也", "没事找事、制造政绩、夸耀功劳——好大喜功，反成祸端。"), "上" to PosInfo("吉凶不现", "汉宣算效，优于孝文，日漓我醇", "日漓我醇，潜有损也", "汉宣帝算功效比孝文帝还强，可淳朴的民风悄悄流失了——急功近利，暗中有损。")), "绩就是功业。做事不见功绩，怎么算完？治学不在多，能以道成就是功；用兵不在多，能使祸乱平定是功。"),
        Ming("101", "育", "育，养也。天地生物，人资以养；君陈一法，人得其养。是故：夫人稚养于母，幼养于父，终身养于天地人君", "水", "", mapOf("初" to PosInfo("吉凶不现", "井渫勿羃，遐迩之汲", "迩迤之汲，养不穷也", "井淘干净、不加井盖，远近的人都来打水——养人之源要常清常通。"), "二" to PosInfo("吉", "刍我黄牛，以耕则收，无忧无忧", "刍我黄牛，养贤也", "把黄牛养好，耕地就有收成——养贤如养牛，厚待贤才，必得其力。"), "三" to PosInfo("凶", "赤子啼饥，观我朵颐，载矜载嗤", "载矜载嗤，莫之恤也", "婴儿饿得哇哇哭，旁人只顾自己吃、还笑他——见苦不救，养而无情。"), "四" to PosInfo("臧", "吐哺铺儿，母瘠子肥，母心之嘻", "母瘠子肥，损上益下也", "母亲把饭喂给孩子，自己瘦、孩子胖，心里还高兴——损己养人，是养育的真义。"), "五" to PosInfo("平", "燕雀之党，自育自养，解而罗网", "解而罗纲，勿扰之也", "燕雀自己会觅食养育，别去张网惊扰——养民要放手，别横加干涉。"), "六" to PosInfo("否", "发廪移粟，东歌西哭", "东歌西哭，不偏及也", "开仓运粮救济，东边的人唱、西边的人哭——好处没均沾，偏了就会出怨。"), "上" to PosInfo("吉凶不现", "井田之行，何富何贫，万国之均", "万国之均，大成也", "井田之法推行，没有贫富悬殊、万国平均——养民之道大成。")), "育就是养育。天地生万物供人取养，君主立一个法度让民众得以养育；所以人幼时靠母亲、少年靠父亲、终身靠天地和君主。"),
        Ming("102", "声", "声，名也。无其实声不溢，无其声人不闻。声溢而崇，德之所以终；人闻而广，业之所以始。故曰：善不积，不足以成名。又曰：三代之王，必先令闻", "火", "", mapOf("初" to PosInfo("吉凶不现", "击磬撞钟，或清或洪", "或清或洪，声从实也", "敲磬有清声、撞钟有洪声——有什么质地就发什么声，名声从实德来。"), "二" to PosInfo("平", "慎守而身，勿为鸮鸣", "勿为鸮鸣，无恶声也", "谨慎守好自身，别学夜枭乱叫招人厌——不求恶名，就是好名。"), "三" to PosInfo("凶", "蔽叶之蜩，其鸣哓哓，蜚鸟之招", "蜚鸟之招，声致殃也", "蝉躲在叶下拼命叫，反把捕食的鸟招来——声张太过，反招祸殃。"), "四" to PosInfo("臧", "空谷来风，有声沨沨", "有声沨沨，匪求之也", "空谷里自然来风、水声淙淙——名声不求自来，是实德所召。"), "五" to PosInfo("否", "鬼啸梁上，弗见其象，人莫之享", "弗见其象，无实也", "像梁上鬼叫，只听声不见形——没实迹的虚名，没人真信。"), "六" to PosInfo("吉", "非雷非霆，四方是闻，蛰者思亨", "蛰者思亨，求自奋也", "不靠雷霆的威吓，名声传遍四方，蛰伏的人听了都想奋起——德声远播，感召天下。"), "上" to PosInfo("吉凶不现", "金声玉振，始终惟令", "始终惟令，不寖消也", "像钟磬合奏、金声玉振，从头到尾都是好名声——始终如一，美名不消。")), "声就是名声。没有实德名声不会外溢，没有名声人们听不到；声满而受崇是德行的终成，闻名而广大是事业的开端。所以说善不积累不足以成名。"),
        Ming("103", "興", "興，起也。仆而復起，衰而更興；前王之澤，後王之能。", "木", "", mapOf("初" to PosInfo("吉凶不现", "選馬修輿，辨道徐駆", "選馬修輿，審所寄也", "先选好马、修好车，辨清道路再慢慢走——兴起之初，谨慎为重。"), "二" to PosInfo("凶", "大饗無饔，撤木無工，有初無終，喪其故宮", "大饗無饔，力不副志也", "想办大宴没有厨子、想拆屋没有工匠——心比天高、力不从心，有始无终，连老家业都丢了。"), "三" to PosInfo("平", "澣垢縫裂，搘欹補缺", "澣垢縫裂，且可依也", "脏了洗、裂了缝、歪了支、缺了补——修修补补，还能撑住局面。"), "四" to PosInfo("臧", "病危得醫，器弊得捶", "病危得醫，佐以明智也", "病到垂危得了好医生、器物坏了有人修补——危难时遇贤助，可起死回生。"), "五" to PosInfo("吉", "椔有枿裁，或爲棟才，熒出于灰，可以焚萊", "枿裁爲棟，天才異也", "枯树发新芽可成栋梁，灰里余烬能复燃燎原——绝处逢生，是天才的兴起。"), "六" to PosInfo("否", "因郄而憩，望遠而唏", "望遠而唏，志力憊也", "逮着机会就歇、望着远方空叹气——志气力气都耗尽了，起不来了。"), "上" to PosInfo("吉凶不现", "總辔操箠，左右在己", "總辔在上，執興替也", "缰绳鞭子都在自己手里，往左往右自己定——兴替之权，操之在己。")), "興就是兴起。跌倒再起来，衰败再振兴；前代君王的恩泽，要靠后代君王的能力。"),
        Ming("104", "痡", "痡，病也。官病於上，民病於下，國以陵夷", "金", "", mapOf("初" to PosInfo("吉凶不现", "外强中懈，恃而不戒", "外强中懈，釁所從也", "外面看着硬、里面已松散，还仗着强硬不设防——祸端就从这来。"), "二" to PosInfo("否", "袪寒得熱，金石之孽", "袪寒得熱，失中節也", "想驱寒反倒上了火——用药失了分寸，治病反致病。"), "三" to PosInfo("凶", "齒拔兒傷，治體得亡", "治體得亡，其醫庸也", "拔颗牙把孩子伤着、治个病把身体治垮——庸医误人，越治越坏。"), "四" to PosInfo("吉", "固本以靜，防微以慎，天不能病", "天不能病，自治详也", "根基牢固、静心调养，小病小患早防——自己调理得好，老天也病不了他。"), "五" to PosInfo("平", "弗益弗擊，輔根引日，以俟明術", "辅根引日，未失也", "不猛下药也不乱攻，先养住根基、拖延时日，等明白医理的人来——不失误，就是保住。"), "六" to PosInfo("臧", "其亡其亡，劑審其方，醫用其良", "其亡其亡，戒慎不败也", "时时提醒「要亡了要亡了」，用药审方、请良医——戒慎恐惧，才能不败。"), "上" to PosInfo("吉凶不现", "膏盲不治，世無良醫", "膏肓之疾，不可如何也", "病已入膏肓，世上再没有良医能救——病到极处，神仙难医。")), "痡就是病。在上位的官吏病了，在下位的百姓病了，国家因此衰败。"),
        Ming("610", "泯", "泯、滅也。熒出于灰，噓之實難；火燎于原，滅之則易。是故周之興也，十五王而不足，及其滅也。一褒娰而有餘，可不戒哉，可不懼哉。", "土", "", mapOf("初" to PosInfo("吉凶不现", "蜩鳴于林，䘺衣絮衾", "蜩鸣絮衾，宜早防也", "蝉叫得欢、衣被已破旧——衰象初露就该早作防备。"), "二" to PosInfo("臧", "微子前見，商祀不殄，其紹如綫", "微子之祀，重存商也", "微子早看出商朝要亡，预先保全，香火像丝线一样续了下来——早见可免灭绝。"), "三" to PosInfo("吉", "婚自竇亡，乃生少康", "夏之不泯，得少康也", "少康从灭亡中逃出生天、复兴夏朝——绝处逢生，灭而后兴。"), "四" to PosInfo("凶", "躬顛血絕，廟夷隴滅", "躬颠血绝，诚可伤也", "身败血绝、宗庙夷平——真到了灭绝之境，可悲可伤。"), "五" to PosInfo("平", "耎志蹙躬，惟运之从", "耎志蹙躬，无以攘也", "意志软弱、缩着身子，只能听凭命运摆布——自己先垮，谁也救不了。"), "六" to PosInfo("否", "水厌其原，木剿其根；波高叶繁，目昧心昏", "水厌其原，何可长也", "水淹了源头、树砍了根，还看着浪高叶茂——根基已坏，迷惑越深，垮得越快。"), "上" to PosInfo("吉凶不现", "前车已覆，瞻彼社屋", "前车之覆，后所惩也", "前面的车已经翻了，抬头看看那倾颓的社屋——前车之鉴，后人要引以为戒。")), "泯就是灭亡。灰里的火星，吹旺很难；燎原的大火，扑灭却容易。周朝兴起历十五王仍嫌不足，灭亡时一个褒姒就足够了，能不警戒吗？"),
        Ming("66", "造", "造、始也。雲雷方屯，開乾闢坤；肇有父子，始立君臣。唱之者聖，和之者賢，為之者仁，成之者天。", "水", "", mapOf("初" to PosInfo("吉凶不现", "太虚测冥，开乾闢坤；万有咸叙，实唯其人", "万有咸叙，人所为也", "混沌初开、乾坤始立，万物各得其序——开创的伟业，终究靠人来完成。"), "二" to PosInfo("吉", "舜禹之禅，汤武之战，天心人愿。", "天心人愿，非利之也。禅战皆义，不为名利。", "舜禹禅让、汤武征伐，都是顺天应人、出于大义，不为私利——合乎道义的开创，大吉。"), "三" to PosInfo("凶", "用不择术，功偕恶积，成艰毁疾", "成艰毁疾，不由德也", "成事不择手段，就算成了也恶贯满盈——不从德行出发，成也难守、毁得也快。"), "四" to PosInfo("臧", "依仁附义，秉时顺理，诛暴诛奸，利物利己", "能利乎物，实自利也", "依着仁、顺着义、合着时机理数去除暴安良——利了别人，其实也利了自己。"), "五" to PosInfo("平", "量时度力，田作言一，规模可则", "规模可则，匪自弃也", "掂量时机和力量，定下统一的规划——量力而行、有章可循，就不算自弃。"), "六" to PosInfo("否", "方春不犁，洎秋而饥，妇子号悲", "洎秋而饥，失时极也", "春天不犁地，秋天一家老小饿得哭——错过天时到极点，后悔莫及。"), "上" to PosInfo("吉凶不现", "立德建名，惟天之命而贡之成，否则祸生", "立德建名，天所命也", "立德建名是承天之命的事，尽力完成它；不然，祸就来了——开创的极致在立德。")), "造就是开始。云雷方起，开天辟地；这才有了父子，立起君臣。开创的是圣人，附和的是贤人，去做的是仁人，成就的是天。"),
        Ming("67", "隆", "隆、盛也。一陽之進，必盛于夏，是謂隆暑，陰則生矣；一陰之進，必底于寒，是謂隆冬，陽亦形焉。是故王者之業，必極盈成，盈成之時，必貴持守，可不念哉。", "火", "", mapOf("初" to PosInfo("吉凶不现", "其忧其勤，日升于西", "其忧其勤，匪进也", "又忧又勤，像太阳从西边升起一样不可能——空忧不行动，不会真正前进。"), "二" to PosInfo("平", "百体四支，勿增勿亏，守之以祇", "体之已完，勿增损也；善守其成，惟能谨也", "身体四肢已长全，别乱增乱减——盛时贵在守成，谨慎持守就是平。"), "三" to PosInfo("凶", "酒肉如陵，钟鼓盈庭，铁刃堕城", "铁刃堕城，守备尽也", "酒肉堆成山、钟鼓响满堂，敌人的刀已经砍进城门——盛极忘备，乐极生悲。"), "四" to PosInfo("臧", "视舟之濡，窒之用袽", "视舟之濡，虑患于谨也", "看见船有一点渗水，赶紧用破絮堵住——盛时见微知著、早防患，是明智。"), "五" to PosInfo("否", "暑至阴生，寒极阳萌，君子畏盈，小人怙成", "小人怙成，危患近也", "暑到顶点阴气就生、寒到极点阳气就萌——君子怕的是太满，小人得意洋洋，危患就来了。"), "六" to PosInfo("吉", "盛不忘衰，安不忘危，一日万几", "万事之微，不可不慎", "兴盛时不忘衰败、安定时不忘危难，日理万机都谨慎——盛而有戒，大吉。"), "上" to PosInfo("吉凶不现", "累土匪易，功亏一篑", "一篑未成，亏九仞也", "堆一座山，差最后一筐土没堆成——盛极之时，最容易功亏一篑。")), "隆就是盛大。阳气进到夏天最盛，叫隆暑，阴气也就生了；王者的基业到了鼎盛，最要紧的是持守，能不记着吗？"),
        Ming("68", "散", "散、消也。氣散而竭，族散而絕，民散而滅。", "木", "", mapOf("初" to PosInfo("吉凶不现", "敝弓之弨，益添與膠", "益添與膠，结以礼信也", "旧弓松了，加点胶重新加固——关系松了，要用礼和信来粘合。"), "二" to PosInfo("凶", "心德之离，微子去之", "微子去之，亲戚离也", "人心和德行都散了，连微子这样的至亲都离开——散从心离开始。"), "三" to PosInfo("平", "守业兢兢，朝露春水", "朝露春水，虽凝易泮也", "守着家业战战兢兢，可它像朝露春冰——看着凝结，太阳一出来就化了。"), "四" to PosInfo("臧", "倒廪虚库，财散人聚", "倒廪虚库，知所散也", "把粮仓厍房散空赈济——该散的时候散，财散了人心聚了。"), "五" to PosInfo("吉", "雾散而星，雍溃而平，盗弃其兵", "盗弃其兵，祸乱释也", "雾散了星星现、水溃了归于平，连盗贼都放下刀兵——积患消散，祸乱解除。"), "六" to PosInfo("否", "积沙防水，水至沙溃", "水至沙溃，不固结也", "用沙子堆堤挡水，水一来全垮——根基不固、人心不聚，一冲就散。"), "上" to PosInfo("吉凶不现", "长夜之宴，虽久必散，达者先见", "达者先见，明始终也", "再长的夜宴也终究要散——通达的人早看见这个结局，好聚好散。")), "散就是消散。气散了就竭，族散了就绝，民散了就灭。"),
        Ming("69", "餘", "餘、終也。天過其度，日之餘也；朔不滿氣，月之餘也；日不復次，嵗之餘也；功德垂後，聖賢之餘也。故天地無餘，則不能變化矣；聖賢無餘，則光澤不遠矣。", "金", "尧舜之德，禹稷之绩，周规孔式，终天无斁。||尧舜周孔，垂世无穷也", emptyMap(), "餘就是终结。天过其度是日的余数，朔不满气是月的余数，日不复次是年的余数；功德流传后世是圣贤的余泽。天地没有余，就不能变化。"),
        Ming("55", "齊", "齊、中也。陰陽不中，則物不生；血氣不中，則體不平；剛柔不中，則德不成；寬猛不中，則政不行。中之用，其至矣呼", "土", "众星拱极，万矢凑的，必不可易||众星万矢，谁能易中也", emptyMap(), "齊就是中。阴阳不中万物不生，血气不中身体不平，刚柔不中德行不成，宽猛不中政令不行。中的用处，真是到了极处！"),
    )
}